function playKitchenChime(force=false){
  if(!soundEnabled&&!force)return;
  try{
    const Ctx=window.AudioContext||window.webkitAudioContext;
    if(!Ctx)return;
    const ctx=new Ctx();
    [880,1174.66].forEach((freq,i)=>{
      const osc=ctx.createOscillator(),gain=ctx.createGain();
      osc.type='sine';osc.frequency.value=freq;
      const start=ctx.currentTime+i*0.14;
      gain.gain.setValueAtTime(0.001,start);
      gain.gain.exponentialRampToValueAtTime(0.22,start+0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001,start+0.55);
      osc.connect(gain);gain.connect(ctx.destination);
      osc.start(start);osc.stop(start+0.56);
    });
  }catch{}
}
function toWhatsAppPhone(phone){let d=String(phone||'').replace(/\D/g,'');if(d.startsWith('0')&&d.length===11)return '234'+d.slice(1);if(d.length===10)return '234'+d;return d}
function genOrderId(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';const arr=new Uint8Array(7);(window.crypto?.getRandomValues?crypto.getRandomValues(arr):arr.forEach((_,i)=>arr[i]=Math.floor(Math.random()*256)));const code=[...arr].map(b=>chars[b%chars.length]).join('');return `RE-${code.slice(0,4)}-${code.slice(4)}`}
function awardPendingOrderCredits(order){if(!order||order.creditsAwarded||!order.pendingCredits)return;const key=phoneKey(order.phone);const target=(customer&&toWhatsAppPhone(customer.phone)===toWhatsAppPhone(order.phone))?customer:accounts[key];if(target){target.credits=Math.max(20,Number(target.credits||20)+order.pendingCredits);target.ledger=target.ledger||[];target.ledger.unshift({date:new Date().toISOString(),description:`Order reward · ${order.id}`,amount:order.pendingCredits,balance:target.credits});if(target===customer)saveCustomer();else{accounts[key]=target;save(STORAGE.accounts,accounts)}}order.creditsAwarded=true;save(STORAGE.orders,orders)}
function customerWhatsAppLink(phone,text){const p=toWhatsAppPhone(phone);return p?`https://wa.me/${p}?text=${encodeURIComponent(text)}`:''}
