// Real-time cross-tab sync so Kitchen Staff tab updates & chimes when Customer tab places an order
window.addEventListener('storage',e=>{
  if(e.key===STORAGE.orders){
    const prevCount=orders.length;
    orders=load(STORAGE.orders,[]);
    if(orders.length>prevCount){
      const newest=orders[orders.length-1];
      playKitchenChime();
      showToast(`🔔 New order ${newest.id} (${newest.fulfillment}) just arrived!`);
    }
    if(adminRole&&$('#adminModal')?.classList.contains('active'))renderAdminDashboard(currentAdminTab);
    if($('#trackModal')?.classList.contains('active'))renderTrackResult($('#trackForm')?.elements.namedItem('orderId')?.value||'');
    if($('#accountModal')?.classList.contains('active')&&customer?.name!=='Guest')renderAccount();
  }else if(e.key===STORAGE.reservations){
    reservations=load(STORAGE.reservations,[]);
    if(adminRole&&$('#adminModal')?.classList.contains('active'))renderAdminDashboard(currentAdminTab);
  }else if(e.key===STORAGE.menu){
    menu=load(STORAGE.menu,seedMenu);
    renderMenu();
    if(adminRole&&$('#adminModal')?.classList.contains('active')&&currentAdminTab==='Menu')renderAdminDashboard('Menu');
  }
});
