// Scroll-triggered reveals, header elevation & active nav Scroll-Spy
(function initMotion(){
  const header=$('.site-header');
  const navLinks=$$('.main-nav a:not(.nav-dashboard)');
  const sections=['home','menu','story','visit'].map(id=>({id,el:$('#'+id)})).filter(s=>s.el);
  const updateNavSpy=()=>{
    const y=window.scrollY+140;
    let activeId='home';
    sections.forEach(s=>{if(y>=s.el.offsetTop)activeId=s.id});
    navLinks.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+activeId));
  };
  let ticking=false;
  const onScroll=()=>{
    if(header)header.classList.toggle('scrolled',window.scrollY>24);
    if(!ticking){ticking=true;requestAnimationFrame(()=>{updateNavSpy();ticking=false})}
  };
  onScroll();
  window.addEventListener('scroll',onScroll,{passive:true});
  const targets=$$('.quick-info > div, .section-heading, .story-image, .story-copy, .perks .eyebrow, .perks h2, .perk-grid article, .catering-card, .review-card, .visit-copy, .map-card, .reserve-card');
  if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches){targets.forEach(el=>el.classList.add('is-visible'));return}
  targets.forEach(el=>{el.classList.add('reveal');const parent=el.parentElement;if(parent&&(parent.classList.contains('perk-grid')||parent.classList.contains('quick-info')||parent.classList.contains('reviews-grid'))){const idx=[...parent.children].indexOf(el);el.style.setProperty('--reveal-delay',`${idx*90}ms`)}});
  const io=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');io.unobserve(entry.target)}})},{threshold:0.12,rootMargin:'0px 0px -40px 0px'});
  targets.forEach(el=>io.observe(el));
})();
